import api from "../api"; // تأكد من استيراد إعدادات axios الخاصة بك
import StudentLayout from "./StudentLayout";

const WILAYAS = ["All","Alger","Oran","Constantine","Annaba","Béjaïa","Tizi Ouzou","Blida","Sétif","Tlemcen","Batna"];
const TYPES   = ["All","On-site","Remote","Hybrid"];
const DOMAINS = ["All","Web Dev","Mobile","Data Science","DevOps","Cybersecurity","AI/ML","Embedded"];

const typeColor = { "On-site":"badge-blue", "Remote":"badge-green", "Hybrid":"badge-orange" };

function OfferCard({ offer, onApply }) {
  const [saved, setSaved] = useState(false);
  return (
    <div className="card border border-slate-200 offer-card p-5 anim-fade-up">
      <div className="flex items-start justify-between gap-3 mb-3">
        <div className="flex items-start gap-3">
          {/* عرض اللوجو كإيموجي أو صورة إذا توفرت من السيرفر */}
          <div className="w-11 h-11 rounded-xl bg-soft border border-soft flex items-center justify-center text-xl shrink-0">
            {offer.logo || "💼"}
          </div>
          <div>
            <h3 className="font-syne font-bold text-slate-800 text-sm leading-snug">{offer.title}</h3>
            {/* عرض اسم الشركة من البيانات المدمجة في السيرفر */}
            <p className="text-xs text-slate-400 mt-0.5">{offer.company_name || "Company"} · {offer.wilaya}</p>
          </div>
        </div>
        <button
          onClick={() => setSaved(s => !s)}
          className={`shrink-0 text-lg transition-all hover:scale-110 ${saved ? "opacity-100" : "opacity-30 hover:opacity-70"}`}
        >
          {saved ? "🔖" : "🔖"}
        </button>
      </div>

      <div className="flex flex-wrap gap-1.5 mb-3">
        <span className={`badge ${typeColor[offer.type] || 'badge-slate'}`}>{offer.type}</span>
        <span className="badge badge-slate">⏱ {offer.duration || "N/A"}</span>
        <span className="badge badge-slate">{offer.domain}</span>
      </div>
      
      <div className="flex flex-wrap gap-1.5 mb-4">
        {offer.skills?.map(s => (
          <span key={s} className="skill-chip">{s}</span>
        ))}
      </div>

      <div className="flex items-center justify-between">
        <div className="text-xs text-slate-400">
          <span className="mr-2">🕐 {offer.posted_at || "Recently"}</span>
          <span>👥 {offer.applicants_count || 0} applicants</span>
        </div>
        <button
          onClick={() => onApply(offer)}
          className="shimmer-btn text-white text-xs font-semibold px-4 py-2 rounded-lg"
        >
          Apply →
        </button>
      </div>
    </div>
  );
}

function ApplyModal({ offer, onClose }) {
  const [step, setStep] = useState(1);
  const [note, setNote] = useState("");
  const [loading, setLoading] = useState(false);
const handleApply = async () => {
    console.log("1. بدء عملية التقديم"); 
    setLoading(true);
    
    try {
        const userStr = localStorage.getItem('user');
        if (!userStr) {
            alert("بيانات المستخدم غير موجودة، يرجى إعادة تسجيل الدخول");
            setLoading(false);
            return;
        }

        const userData = JSON.parse(userStr);
        
        // تصحيح مهم: استخدم offer.id (وليس OfferId بحرف كبير)
        // وتأكد من جلب المعرف الصحيح للطالب من بيانات التخزين
        const payload = {
            offer: offer.id, 
            message: note,
            student: userData.id // السيرفر يتوقع الـ ID الخاص ببروفايل الطالب
        };
        
        console.log("4. البيانات المرسلة (Payload):", payload);

        // إرسال الطلب للسيرفر
        const response = await api.post('applications/', payload);
        
        console.log("5. تم التقديم بنجاح:", response.data);
        setStep(2); 

    } catch (err) {
        console.error("6. خطأ في التقديم:", err);
        if (err.response) {
            // عرض رسالة الخطأ القادمة من Django (مثل: لقد قدمت مسبقاً)
            const serverError = err.response.data.detail || JSON.stringify(err.response.data);
            alert("تنبيه: " + serverError);
        } else {
            alert("حدث خطأ في الاتصال بالسيرفر");
        }
    } finally {
        setLoading(false);
        console.log("7. انتهت العملية");
    }
};

 

  if (!offer) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/50 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-md p-6 z-10 anim-fade-up">
        {step === 1 && (
          <>
            <div className="flex items-center gap-3 mb-5">
              <div className="w-12 h-12 rounded-xl bg-soft border border-soft flex items-center justify-center text-2xl">{offer.logo || "💼"}</div>
              <div>
                <h3 className="font-syne font-bold text-slate-900 text-lg">{offer.title}</h3>
                <p className="text-sm text-slate-400">{offer.company_name}</p>
              </div>
            </div>
            <div className="mb-4">
              <label className="block text-sm font-semibold text-slate-700 mb-1.5">Cover note (optional)</label>
              <textarea
                rows={3}
                value={note}
                onChange={e => setNote(e.target.value)}
                placeholder="Why are you the right fit for this internship?"
                className="input-field resize-none w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <div className="text-xs text-slate-400 bg-soft rounded-lg px-3 py-2 mb-5 italic">
              📎 Your digital CV and skills profile will be sent automatically.
            </div>
            <div className="flex gap-3">
              <button onClick={onClose} className="flex-1 py-2.5 rounded-xl border border-slate-200 text-sm font-medium text-slate-600 hover:bg-cream/30 transition-colors">Cancel</button>
              <button 
                onClick={handleApply} 
                disabled={loading}
                className="flex-1 shimmer-btn text-white text-sm font-semibold py-2.5 rounded-xl disabled:opacity-50"
              >
                {loading ? "Sending..." : "Send application →"}
              </button>
            </div>
          </>
        )}
        {step === 2 && (
          <div className="text-center py-4">
            <div className="text-5xl mb-4">🎉</div>
            <h3 className="font-syne font-bold text-slate-900 text-xl mb-2">Application sent!</h3>
            <p className="text-sm text-slate-500 font-light mb-6">Your profile has been sent to <strong className="text-slate-700">{offer.company_name}</strong>.</p>
            <button onClick={onClose} className="shimmer-btn text-white text-sm font-semibold px-8 py-2.5 rounded-xl">Done</button>
          </div>
        )}
      </div>
    </div>
  );
}

export default function StudentSearch() {
  const [offers, setOffers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [wilaya, setWilaya] = useState("All");
  const [type,   setType]   = useState("All");
  const [domain, setDomain] = useState("All");
  const [applying, setApplying] = useState(null);

  // جلب البيانات من السيرفر عند تحميل المكون
  useEffect(() => {
    const fetchOffers = async () => {
      try {
        const response = await api.get('offers/');
        setOffers(response?.data);
      } catch (err) {
        console.error("Error fetching offers:", err);
      } finally {
        setLoading(false);
      }
    };
    fetchOffers();
  }, []);

  const filtered = offers.filter(o => {
    const q = search.toLowerCase();
    const matchQ = !q|| (o.company_name && o.company_name.toLowerCase().includes(q)) || o.skills?.some(s => s.toLowerCase().includes(q));
    const matchW = wilaya==="All" || o.wilaya===wilaya;
    const matchT = type==="All"   || o.type===type;
    const matchD = domain==="All" || o.domain===domain;
    return matchQ && matchW && matchT && matchD;
  });

  return (
    <StudentLayout active="search">
      <div className="p-5 md:p-8">

        {/* Header */}
        <div className="anim-fade-up mb-6">
          <p className="text-xs font-semibold text-[#2E7DF7] uppercase tracking-widest mb-1">Offers</p>
          <h1 className="font-syne font-extrabold text-slate-900 text-2xl md:text-3xl tracking-tight">
            Find your internship
          </h1>
          <p className="text-slate-400 text-sm font-light mt-0.5">
            {loading ? "Loading offers..." : `${filtered.length} offers matching your profile`}
          </p>
        </div>
        {/* Search + filters */}
        <div className="anim-fade-up anim-d1 card border border-slate-200 p-4 mb-6">
          <div className="flex flex-col md:flex-row gap-3">
            <div className="flex-1 relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm">🔍</span>
              <input
                type="text"
                placeholder="Search by title, company or skill..."
                value={search}
                onChange={e => setSearch(e.target.value)}
                className="input-field pl-9 w-full p-2 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <select value={wilaya} onChange={e=>setWilaya(e.target.value)} className="input-field md:w-36 border p-2 rounded-xl outline-none">
              {WILAYAS.map(w=><option key={w} value={w}>{w}</option>)}
            </select>
            <select value={type}   onChange={e=>setType(e.target.value)}   className="input-field md:w-32 border p-2 rounded-xl outline-none">
              {TYPES.map(t=><option key={t} value={t}>{t}</option>)}
            </select>
            <select value={domain} onChange={e=>setDomain(e.target.value)} className="input-field md:w-36 border p-2 rounded-xl outline-none">
              {DOMAINS.map(d=><option key={d} value={d}>{d}</option>)}
            </select>
            {(search !== "" || type!=="All" || domain!=="All") && (
              <button
                onClick={()=>{setSearch("");setWilaya("All");setType("All");setDomain("All");}}
                className="text-xs font-medium text-slate-500 hover:text-[#b5394e] border border-slate-200 px-3 py-2 rounded-xl transition-colors whitespace-nowrap"
              >
                Clear ✕
              </button>
            )}
          </div>
        </div>

        {/* Results grid */}
        {loading ? (
           <div className="text-center py-20">
             <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
             <p className="mt-4 text-slate-400">Fetching live offers...</p>
           </div>
        ) : filtered.length > 0 ? (
          <div className="anim-fade-up anim-d2 grid md:grid-cols-2 xl:grid-cols-3 gap-4">
            {filtered.map(offer => (
              <OfferCard key={offer.id} offer={offer} onApply={setApplying} />
            ))}
          </div>
        ) : (
          <div className="anim-fade-up anim-d2 text-center py-20">
            <div className="text-5xl mb-3">🔍</div>
            <h3 className="font-syne font-bold text-slate-700 text-lg mb-1">No offers found</h3>
            <p className="text-sm text-slate-400">Try adjusting your filters or search terms.</p>
          </div>
        )}

      </div>

      {applying && <ApplyModal offer={applying} onClose={() => setApplying(null)} />}
    </StudentLayout>
  );
}
